import{_ as r,a0 as n,w as i,s as m,ao as l,I as s,x as a,a1 as o,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"命令行下使用 Mop 监视股票价格 | LCTT x X-CMD","titleTemplate":false,"description":"命令行下使用 Mop 监视股票价格 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令行下使用 Mop 监视股票价格 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令行下使用 Mop 监视股票价格 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151012 How to Monitor Stock Prices from Ubuntu Command Line Using Mop","title":"命令行下使用 Mop 监视股票价格","tag":"201511","desc":""},"relativePath":"201511/20151012 How to Monitor Stock Prices from Ubuntu Command Line Using Mop.md","filePath":"[post].md"}'),d={name:"201511/20151012 How to Monitor Stock Prices from Ubuntu Command Line Using Mop.md"};function h(c,e,u,g,k,w){const t=n("Link");return i(),m("div",null,[e[13]||(e[13]=l(`<h1 id="命令行下使用-mop-监视股票价格" tabindex="-1">命令行下使用 Mop 监视股票价格 <a class="header-anchor" href="#命令行下使用-mop-监视股票价格" aria-label="Permalink to “命令行下使用 Mop 监视股票价格”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-featured-new.jpg" alt=""></p><p>有一份隐性收入通常很不错，特别是当你可以轻松的协调业余和全职工作。如果你的日常工作使用了联网的电脑，交易股票就是一个获取额外收入的很流行的选项。</p><p>但是目前只有很少的股票监视软件可以运行在 linux 上，其中大多数还是基于图形界面的。如果你是一个 Linux 专家，并且大量的工作时间是在没有图形界面的电脑上呢？你是不是就没办法了？不，还是有一些命令行下的股票追踪工具，包括Mop，也就是本文要聊一聊的工具。</p><h3 id="mop" tabindex="-1">Mop <a class="header-anchor" href="#mop" aria-label="Permalink to “Mop”">​</a></h3><p>Mop，如上所述，是一个命令行下连续显示和更新美股和独立股票信息的工具。使用 GO 语言实现的，是 Michael Dvorkin 的智慧结晶。</p><h3 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to “下载安装”">​</a></h3><p>因为这个项目使用 GO 实现的，所以你要做的第一步是在你的计算机上安装这种编程语言，下面就是在 Debian 系的系统，比如 Ubuntu 上安装 GO 的步骤：</p><pre><code>sudo apt-get install golang
mkdir ~/workspace
echo &#39;export GOPATH=&quot;$HOME/workspace&quot;&#39; &gt;&gt; ~/.bashrc
source ~/.bashrc
</code></pre><p>GO 安装好后的下一步是安装 Mop 工具和配置环境，你要做的是运行下面的命令：</p><pre><code>sudo apt-get install git
go get github.com/michaeldv/mop
cd $GOPATH/src/github.com/michaeldv/mop
make install
export PATH=&quot;$PATH:$GOPATH/bin&quot;
</code></pre><p>完成之后就可以运行下面的命令执行 Mop：</p><pre><code>cmd
</code></pre><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><p>当你第一次运行 Mop 时，你会看到类似下面的输出信息：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-first-run.jpg" alt=""></p><p>如你所见，这些输出信息—— 周期性自动刷新 ——包含了主要几个交易所和个股的信息。</p><h3 id="添加删除股票" tabindex="-1">添加删除股票 <a class="header-anchor" href="#添加删除股票" aria-label="Permalink to “添加删除股票”">​</a></h3><p>Mop 允许你轻松的从输出列表上添加/删除个股信息。要添加，你全部要做的是按“+”和输入股票名称。举个例子，下图就是添加 Facebook (FB) 到列表里。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-add-stock.png" alt=""></p><p>我按下了“+”键，就出现了包含文本“Add tickers：”的一列，提示我添加股票名称—— 我添加了 FB 然后按下回车。输出列表更新了，我添加的新股票也出现在列表了：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-stock-added.png" alt=""></p><p>类似的，你可以使用“-”键和提供股票名称删除一个股票。</p><h4 id="根据价格分组" tabindex="-1">根据价格分组 <a class="header-anchor" href="#根据价格分组" aria-label="Permalink to “根据价格分组”">​</a></h4><p>还有一个把股票分组的办法：依据他们的股价升跌，你所要做的就是按下“g”键。接下来，股票会分组显示：升的在一起使用绿色字体显示，而下跌的股票会黑色字体显示。</p><p>如下所示：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-group-stocks-profit-loss.png" alt=""></p><h4 id="列排序" tabindex="-1">列排序 <a class="header-anchor" href="#列排序" aria-label="Permalink to “列排序”">​</a></h4><p>Mop 同时也允许你根据不同的列类型改变排序规则。这种用法需要你按下“o”（这个命令默认使用第一列的值来排序），然后使用左右键来选择你要排序的列。完成之后按下回车对内容重新排序。</p><p>举个例子，下面的截图就是根据输出内容的第一列、按照字母表排序之后的结果。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-change-order.png" alt=""></p><p><strong>注意</strong>: 为了更好的理解，和前面的截屏对比一下。</p><h4 id="其他选项" tabindex="-1">其他选项 <a class="header-anchor" href="#其他选项" aria-label="Permalink to “其他选项”">​</a></h4><p>其它的可用选项包括“p”：暂停市场和股票信息更新，“q”或者“esc” 来退出命令行程序，“?”显示帮助页。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/09/mop-help.png" alt=""></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>Mop 是一个基础的股票监控工具，并没有提供太多的特性，只提供了它所声称的功能。很明显，这个工具并不是为专业股票交易者提供的，而仅仅为你在只有命令行的机器上得体的提供了一个跟踪股票信息的选择。</p><hr>`,38)),s("p",null,[e[1]||(e[1]=a("via: ",-1)),o(t,{href:"https://www.maketecheasier.com/monitor-stock-prices-ubuntu-command-line/"},{default:p(()=>[...e[0]||(e[0]=[a("https://www.maketecheasier.com/monitor-stock-prices-ubuntu-command-line/",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=a("作者：",-1)),o(t,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:p(()=>[...e[2]||(e[2]=[a("Himanshu Arora",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),o(t,{href:"https://github.com/oska874"},{default:p(()=>[...e[3]||(e[3]=[a("oska874",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),o(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),s("p",null,[e[10]||(e[10]=a("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创编译，",-1)),o(t,{href:"https://linux.cn/"},{default:p(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const T=r(d,[["render",h]]);export{M as __pageData,T as default};
